// IndexedDB 存储模块 - 替代 chrome.storage.local
const DB_NAME = 'SnapScribeDB';
const DB_VERSION = 1;
const STORE_NAME = 'recordings';

// 压缩图片质量 (0-1)，越低文件越小
const COMPRESS_QUALITY = 0.7;
// 最大宽度/高度，超过则缩放
const MAX_IMAGE_SIZE = 1920;

let db = null;

// 初始化 IndexedDB
async function initDB() {
    if (db) return db;
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onerror = () => reject(request.error);
        request.onsuccess = () => { db = request.result; resolve(db); };
        request.onupgradeneeded = (event) => {
            const database = event.target.result;
            if (!database.objectStoreNames.contains(STORE_NAME)) {
                database.createObjectStore(STORE_NAME, { keyPath: 'id' });
            }
        };
    });
}

// 压缩图片
async function compressImage(dataUrl) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            let { width, height } = img;
            
            // 缩放图片
            if (width > MAX_IMAGE_SIZE || height > MAX_IMAGE_SIZE) {
                const ratio = Math.min(MAX_IMAGE_SIZE / width, MAX_IMAGE_SIZE / height);
                width = Math.round(width * ratio);
                height = Math.round(height * ratio);
            }
            
            const canvas = document.createElement('canvas');
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, width, height);
            
            // 压缩为 JPEG
            const compressed = canvas.toDataURL('image/jpeg', COMPRESS_QUALITY);
            
            const originalSize = (dataUrl.length * 0.75).toFixed(0);
            const newSize = (compressed.length * 0.75).toFixed(0);
            console.log(`[Compress] 原大小: ${(originalSize/1024).toFixed(1)}KB -> 压缩后: ${(newSize/1024).toFixed(1)}KB`);
            
            resolve(compressed);
        };
        img.onerror = () => reject(new Error('图片加载失败'));
        img.src = dataUrl;
    });
}

// 保存录制数据
async function saveRecordingData(data) {
    try {
        await initDB();
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        
        const record = {
            id: 'lastRecording',
            steps: data.steps,
            savedAt: Date.now()
        };
        
        store.put(record);
        console.log('[IndexedDB] 保存成功，步骤数:', data.steps.length);
        return true;
    } catch (e) {
        console.error('[IndexedDB] 保存失败:', e);
        return false;
    }
}

// 加载录制数据
async function loadRecordingData() {
    try {
        await initDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_NAME], 'readonly');
            const store = transaction.objectStore(STORE_NAME);
            const request = store.get('lastRecording');
            
            request.onsuccess = () => {
                const result = request.result;
                if (result) {
                    console.log('[IndexedDB] 加载成功，步骤数:', result.steps ? result.steps.length : 0);
                    resolve(result);
                } else {
                    resolve(null);
                }
            };
            request.onerror = () => reject(request.error);
        });
    } catch (e) {
        console.error('[IndexedDB] 加载失败:', e);
        return null;
    }
}

// 清除录制数据
async function clearRecordingData() {
    try {
        await initDB();
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        store.delete('lastRecording');
        console.log('[IndexedDB] 数据已清除');
        return true;
    } catch (e) {
        console.error('[IndexedDB] 清除失败:', e);
        return false;
    }
}

// 获取存储使用情况
async function getStorageInfo() {
    try {
        await initDB();
        return new Promise((resolve) => {
            const transaction = db.transaction([STORE_NAME], 'readonly');
            const store = transaction.objectStore(STORE_NAME);
            const request = store.get('lastRecording');
            
            request.onsuccess = () => {
                const result = request.result;
                if (result) {
                    const steps = result.steps || [];
                    let totalSize = 0;
                    steps.forEach((step, i) => {
                        if (step.screenshot) {
                            totalSize += step.screenshot.length * 0.75; // base64 转字节
                        }
                    });
                    resolve({
                        stepCount: steps.length,
                        totalSize: Math.round(totalSize),
                        savedAt: result.savedAt
                    });
                } else {
                    resolve({ stepCount: 0, totalSize: 0 });
                }
            };
            request.onerror = () => resolve({ stepCount: 0, totalSize: 0 });
        });
    } catch (e) {
        return { stepCount: 0, totalSize: 0 };
    }
}
